func TestLoadDefaultsToBrowserHTMLAcceptHeader(t *testing.T) {
	t.Setenv("NOON_AE_CONFIG", filepath.Join(t.TempDir(), "missing.toml"))

	cfg, err := Load("")
	if err != nil {
		t.Fatalf("Load() error = %v", err)
	}
	if got := cfg.Headers["Accept"]; got != browserHTMLAcceptHeader {
		t.Fatalf("Accept = %q, want %q", got, browserHTMLAcceptHeader)
	}
}

func TestLoadPreservesConfiguredAcceptHeader(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "config.toml")
	if err := os.WriteFile(path, []byte("[headers]\nAccept = \"text/html\"\nX-Test = \"1\"\n"), 0o600); err != nil {
		t.Fatalf("writing config: %v", err)
	}

	cfg, err := Load(path)
	if err != nil {
		t.Fatalf("Load() error = %v", err)
	}
	if got := cfg.Headers["Accept"]; got != "text/html" {
		t.Fatalf("Accept = %q, want configured value", got)
	}
	if got := cfg.Headers["X-Test"]; got != "1" {
		t.Fatalf("X-Test = %q, want 1", got)
	}
}
